import { lazy } from 'react';
import { Navigate, useSearchParams } from 'react-router-dom';
import { DoorOpen as IcDoorOpen, ListChecks as IcListChecks } from 'lucide-react';
import { TabHub } from '@/components/pulse-ui';

/**
 * Exit Management — hub page for the Human Resources menu.
 *
 * Generated by the 2026-09-16 information-architecture pass as "Exit &
 * Probation". Probation moved out to its own menu row (Probation Management) —
 * confirming a new joiner is not part of anyone leaving — so this hub now holds
 * only the exit workflow: the exit desk (resignations, notice, F&F, interviews,
 * clearance) and the offboarding checklist that runs alongside it.
 *
 * The page key stays ExitCenter so existing URLs, Page Access grants and
 * role tests keep resolving. Each page below keeps its NAV_ITEMS entry marked
 * `inHub: 'ExitCenter'`, so getSectionForPage() still resolves it and every
 * role gate behaves exactly as it did when each was its own row. TabHub
 * re-checks each tab with canRoleOpenPage() before drawing it.
 */
const Offboarding = lazy(() => import('./Offboarding'));
const ExitManagement = lazy(() => import('./ExitManagement'));

export const TABS = [
  { id: 'exit', label: 'Exits & Settlement', icon: IcDoorOpen, page: 'ExitManagement', Component: ExitManagement },
  { id: 'offboarding', label: 'Offboarding Checklist', icon: IcListChecks, page: 'Offboarding', Component: Offboarding },
];

export default function ExitCenter({ setPage }) {
  const [sp] = useSearchParams();
  // `?tab=probation` links predate the split; send them to the probation page
  // rather than silently landing on the first exit tab. Same HR section, so the
  // viewer's access is unchanged.
  if (sp.get('tab') === 'probation') return <Navigate to="/Probation" replace />;

  return (
    <TabHub
      icon={IcDoorOpen}
      eyebrow="Human Resources"
      title="Exit Management"
      subtitle="Resignations, notice, clearance, exit interviews, full & final settlement and offboarding checklists"
      tabs={TABS}
      setPage={setPage}
    />
  );
}
